-- 3. Listings
INSERT OR REPLACE INTO listings (id, seller_id, category_id, title, slug, description, price, original_price, is_negotiable, min_offer_price, condition, completeness, purchase_year, warranty_until, has_original_receipt, status, view_count, offer_count, favorite_count, province, city, district, postal_code, is_cod_available, cod_meeting_point, specs, created_at, updated_at) VALUES
('item-1', 'usr-seller-1', 'cat-gadget', 'iPhone 13 Pro 128GB Sierra Blue Resmi iBox Mulus 96%', 'iphone-13-pro-128gb-sierra-blue-resmi-ibox-mulus-96', 'Dijual iPhone 13 Pro 128GB warna Sierra Blue garansi resmi iBox (PA/A). Kondisi fisik mulus terawat 96%, selalu pakai case dan tempered glass sejak hari pertama. Battery Health 87% original belum pernah servis/bongkar. Face ID, True Tone, 3uTools 100% hijau semua normal. Kelengkapan fullset dus original, kabel type-c original bawaan, sticker apple.', 9850000, 18499000, 1, 9200000, 'LIKE_NEW', '["FULLSET","WITH_RECEIPT"]', 2023, NULL, 1, 'ACTIVE', 384, 8, 42, 'DKI Jakarta', 'Jakarta Selatan', 'Kebayoran Baru', '12130', 1, 'Gandaria City / Blok M Plaza', '{"storage":"128 GB","color":"Sierra Blue","batteryHealth":"87%","region":"PA/A (iBox Indonesia)","faceId":"Normal 100%","trueTone":"Active"}', '2026-08-30T14:30:00Z', '2026-08-30T14:30:00Z'),
('item-2', 'usr-seller-2', 'cat-laptop', 'MacBook Pro 14" M1 Pro 16GB / 512GB Space Grey Fullset Garansi Habis', 'macbook-pro-14-m1-pro-16gb-512gb-space-grey-fullset', 'MacBook Pro 14 inci M1 Pro (8-Core CPU, 14-Core GPU, 16GB Unified RAM, 512GB SSD). Pemakaian harian untuk koding. Bodi 94% mulus tidak ada dent/penyok, hanya baret halus di bawah. Layar Liquid Retina XDR mulus no dead pixel/staingate. Cycle Count 165 (Normal). Fullset dus, charger MagSafe 3 67W asli bawaan.', 18200000, 28999000, 1, 17000000, 'USED_EXCELLENT', '["FULLSET","BOX_UNIT"]', 2022, NULL, 0, 'ACTIVE', 612, 12, 78, 'Jawa Barat', 'Bandung', 'Coblong (Dago)', '40132', 1, 'Starbucks Dago / Cihampelas Walk', '{"processor":"Apple M1 Pro (8-Core)","ram":"16 GB","storage":"512 GB SSD","cycleCount":165,"screenSize":"14.2 Inch Liquid Retina XDR"}', '2026-08-29T10:00:00Z', '2026-08-30T10:00:00Z'),
('item-3', 'usr-seller-1', 'cat-kamera', 'Sony Alpha A6400 Body + Lensa Sigma 30mm F1.4 DC DN Shutter Count 4.2k', 'sony-alpha-a6400-body-lensa-sigma-30mm-f14', 'Dijual sepaket kamera mirrorless Sony A6400 + Lensa bokeh tajam Sigma 30mm f/1.4. Shutter count baru 4.200 (sangat rendah). Karet kencang, sensor bersih no jamur/debu, autofokus super cepat. Bonus filter UV Hoya, baterai cadangan Kingma 2 pcs + dual charger.', 13500000, 17800000, 1, 12700000, 'USED_EXCELLENT', '["FULLSET","BOX_UNIT"]', 2023, NULL, 1, 'ACTIVE', 420, 5, 39, 'Jawa Timur', 'Surabaya', 'Gubeng', '60281', 1, 'Tunjungan Plaza / Galaxy Mall', '{"shutterCount":4200,"sensor":"24.2 MP APS-C Exmor CMOS","lens":"Sigma 30mm f/1.4 DC DN Contemporary","autofocus":"Real-time Eye AF"}', '2026-08-28T09:15:00Z', '2026-08-28T09:15:00Z'),
('item-4', 'usr-seller-2', 'cat-game', 'PlayStation 5 (PS5) Digital Edition CFI-1200 + 2 Stik DualSense Ori', 'ps5-digital-edition-cfi-1200-2-stik-dualsense', 'Dijual PS5 Digital CFI-1200 (seri dingin & hening). Kondisi 98% like new jarang dimainkan karena sibuk kantor. Termasuk 2 Controller DualSense Original no drift sama sekali. Dus buku kabel HDMI ultra high speed lengkap.', 6400000, 8500000, 1, 6000000, 'LIKE_NEW', '["FULLSET","BOX_UNIT"]', 2023, NULL, 0, 'ACTIVE', 530, 9, 56, 'Banten', 'Tangerang Selatan', 'Serpong (BSD)', '15310', 1, 'The Breeze BSD / AEON Mall', '{"model":"CFI-1200B Digital","storage":"825 GB Custom SSD","controller":"2x DualSense Wireless"}', '2026-08-27T16:00:00Z', '2026-08-27T16:00:00Z'),
('item-5', 'usr-seller-1', 'cat-fashion', 'Nike Dunk Low Retro White Black "Panda" Size 42.5 / US 9 Original', 'nike-dunk-low-retro-panda-size-42-5-original', 'Sepatu Nike Dunk Low Panda original beli di Hoops Point. Kondisi 88% pemakaian terawat, outsole bintang masih tebal, insole logo Nike masih utuh, toebox minim crease karena pakai crease protector. Replace box Nike original.', 1150000, 1899000, 1, 1000000, 'USED_GOOD', '["UNIT_ONLY"]', 2023, NULL, 1, 'ACTIVE', 290, 4, 27, 'DI Yogyakarta', 'Yogyakarta', 'Depok Sleman', '55281', 1, 'Pakuwon Mall Jogja / Cafe Kaliurang', '{"size":"42.5 EUR / US 9","colorway":"White / Black","authenticity":"100% Original Verified"}', '2026-08-26T11:20:00Z', '2026-08-26T11:20:00Z');

